#!/bin/bash\n\n# قائمة أمرية شاملة لإنشاء وتشغيل Codespace من tapflow الأصلي\n# Complete Command Guide for tapflow Codespace\n\necho \"========================================\"\necho \"tapflow Codespace - دليل الأوامر الكامل\"\necho \"========================================\"\necho \"\"\n\n# ===================================\n# 1. إنشاء Codespace\n# ===================================\n\necho \"[1️⃣] إنشاء Codespace من tapflow الأصلي\"\necho \"---\"\necho \"\"\necho \"الطريقة الأولى: عبر الواجهة (الأسهل)\"\necho \"1. افتح: https://github.com/jo-duchan/tapflow\"\necho \"2. اضغط على 'Code' (الزر الأخضر)\"\necho \"3. اختر 'Codespaces'\"\necho \"4. اضغط 'Create codespace on main'\"\necho \"5. انتظر حتى ينتهي التثبيت (عادة 2-3 دقائق)\"\necho \"\"\n\necho \"الطريقة الثانية: عبر GitHub CLI\"\necho \"\"\necho \"# تثبيت GitHub CLI (إذا لم يكن مثبتاً)\"\necho \"# https://cli.github.com\"\necho \"\"\necho \"# إنشاء Codespace\"\necho \"gh codespace create -r jo-duchan/tapflow\"\necho \"\"\necho \"# فتح Codespace في المتصفح\"\necho \"gh codespace code -r jo-duchan/tapflow\"\necho \"\"\n\necho \"الطريقة الثالثة: Fork + Codespace (للمساهمة)\"\necho \"\"\necho \"# 1. Fork المستودع من https://github.com/jo-duchan/tapflow\"\necho \"# 2. انتظر انتهاء الـ fork\"\necho \"# 3. ثم:\"\necho \"gh codespace create -r YOUR_USERNAME/tapflow\"\necho \"\"\n\n# ===================================\n# 2. بعد فتح Codespace\n# ===================================\n\necho \"\"\necho \"[2️⃣] داخل Codespace - تثبيت المتعلقات\"\necho \"---\"\necho \"\"\necho \"# تحديث النظام\"\necho \"sudo apt update && sudo apt upgrade -y\"\necho \"\"\necho \"# التحقق من الإصدارات\"\necho \"node --version   # يجب أن يكون >= 22\"\necho \"npm --version\"\necho \"pnpm --version\"\necho \"\"\necho \"# تفعيل pnpm إذا لم يكن مفعلاً\"\necho \"corepack enable pnpm\"\necho \"\"\necho \"# تثبيت المتعلقات\"\necho \"pnpm install\"\necho \"\"\n\n# ===================================\n# 3. تشغيل بيئة التطوير\n# ===================================\n\necho \"\"\necho \"[3️⃣] تشغيل بيئة التطوير\"\necho \"---\"\necho \"\"\n\necho \"الخيار الأول: التطوير المحدود (موصى به للبدايات)\"\necho \"\"\necho \"pnpm dev:lean\"\necho \"\"\necho \"✓ يشغل: Relay + Dashboard (بدون وكلاء أجهزة محاكاة حقيقية)\"\necho \"✓ مناسب لـ: Linux/Codespace\"\necho \"✓ المنافذ: http://localhost:5173 (Dashboard)\"\necho \"\"\n\necho \"الخيار الثاني: التطوير مع وكلاء محاكاة\"\necho \"\"\necho \"pnpm dev:pool\"\necho \"\"\necho \"✓ يشغل: Relay + Dashboard + Mock Agents\"\necho \"✓ مناسب لـ: اختبار الواجهة مع محاكيات مزيفة\"\necho \"✓ المنافذ: http://localhost:5173 (Dashboard)\"\necho \"\"\n\necho \"الخيار الثالث: التطوير الكامل\"\necho \"\"\necho \"pnpm dev\"\necho \"\"\necho \"✓ يشغل: كل شيء (Relay + Dashboard + iOS Agent + Android Agent)\"\necho \"⚠️ ملاحظة: قد لا تعمل الأجهزة المحاكاة على Linux\"\necho \"✓ المنافذ: http://localhost:4000 (Relay) + http://localhost:5173 (Dashboard)\"\necho \"\"\n\n# ===================================\n# 4. أوامر البناء والاختبار\n# ===================================\n\necho \"\"\necho \"[4️⃣] أوامر البناء والاختبار\"\necho \"---\"\necho \"\"\necho \"# بناء المشروع\"\necho \"pnpm build\"\necho \"\"\necho \"# تشغيل الاختبارات\"\necho \"pnpm test\"\necho \"\"\necho \"# اختبار السكريبتات فقط\"\necho \"pnpm test:scripts\"\necho \"\"\necho \"# فحص الكود (Linting)\"\necho \"pnpm lint\"\necho \"\"\necho \"# فحص أنواع TypeScript\"\necho \"pnpm typecheck\"\necho \"\"\n\n# ===================================\n# 5. أوامر التشخيص والإعدادات\n# ===================================\n\necho \"\"\necho \"[5️⃣] أوامر التشخيص والإعدادات\"\necho \"---\"\necho \"\"\necho \"# التحقق من المتطلبات\"\necho \"pnpm doctor\"\necho \"\"\necho \"# إعادة تعيين المحاكي والمحاكاة\"\necho \"pnpm reset\"\necho \"\"\necho \"# قائمة الأجهزة المتاحة\"\necho \"pnpm devices\"\necho \"\"\necho \"# عرض حالة الوكلاء والأجهزة\"\necho \"pnpm status\"\necho \"\"\n\n# ===================================\n# 6. أوامر التطوير المتقدمة\n# ===================================\n\necho \"\"\necho \"[6️⃣] أوامر التطوير المتقدمة\"\necho \"---\"\necho \"\"\necho \"# توقيف بيئة التطوير\"\necho \"pnpm dev:down\"\necho \"\"\necho \"# إعادة seed قاعدة البيانات\"\necho \"pnpm seed\"\necho \"\"\necho \"# إعادة seed البيانات التجريبية\"\necho \"pnpm seed:demo\"\necho \"\"\necho \"# تشغيل MCP Server (للوكلاء الذكيين)\"\necho \"pnpm mcp\"\necho \"\"\necho \"# إعداد ما قبل الإطلاق\"\necho \"pnpm pre-release\"\necho \"\"\n\n# ===================================\n# 7. أوامر التوثيق\n# ===================================\n\necho \"\"\necho \"[7️⃣] أوامر التوثيق\"\necho \"---\"\necho \"\"\necho \"# تشغيل بيئة التوثيق\"\necho \"pnpm docs:dev\"\necho \"\"\necho \"# بناء التوثيق\"\necho \"pnpm docs:build\"\necho \"\"\necho \"# معاينة التوثيق\"\necho \"pnpm docs:preview\"\necho \"\"\n\n# ===================================\n# 8. أوامر الإصدار والنشر\n# ===================================\n\necho \"\"\necho \"[8️⃣] أوامر الإصدار والنشر\"\necho \"---\"\necho \"\"\necho \"# إنشاء changeset (قبل الإصدار)\"\necho \"pnpm changeset\"\necho \"\"\necho \"# التحقق من changesets\"\necho \"pnpm changeset:check\"\necho \"\"\necho \"# تدقيق changesets\"\necho \"pnpm changeset:audit\"\necho \"\"\necho \"# تحديث الإصدار\"\necho \"pnpm version\"\necho \"\"\necho \"# بناء ونشر\"\necho \"pnpm release\"\necho \"\"\n\n# ===================================\n# 9. المنافذ المتاحة\n# ===================================\n\necho \"\"\necho \"[9️⃣] المنافذ المتاحة في Codespace\"\necho \"---\"\necho \"\"\necho \"┌─────────┬──────────────────────┬─────────────────────────────┐\"\necho \"│ المنفذ  │ الخدمة               │ الرابط                      │\"\necho \"├─────────┼──────────────────────┼─────────────────────────────┤\"\necho \"│ 4000    │ Relay Server         │ http://localhost:4000       │\"\necho \"│ 5173    │ Dashboard Dev        │ http://localhost:5173       │\"\necho \"│ 6006    │ Storybook            │ http://localhost:6006       │\"\necho \"└─────────┴──────────────────────┴─────────────────────────────┘\"\necho \"\"\n\n# ===================================\n# 10. نصائح مهمة\n# ===================================\n\necho \"\"\necho \"[🔟] نصائح مهمة\"\necho \"---\"\necho \"\"\necho \"✅ ابدأ بـ: pnpm dev:lean\"\necho \"   (هذا هو الخيار الأمثل للبدايات على Codespace)\"\necho \"\"\necho \"✅ إذا أردت مراقبة سجلات المشروع:\"\necho \"   pnpm logs\"\necho \"\"\necho \"✅ لإيقاف البيئة:\"\necho \"   Ctrl+C في الطرفية\"\necho \"\"\necho \"✅ للعودة للتطوير:\"\necho \"   pnpm dev:lean (مرة أخرى)\"\necho \"\"\necho \"⚠️ محاكيات iOS/Android الحقيقية تحتاج macOS\"\necho \"   استخدم pnpm dev:lean أو pnpm dev:pool على Codespace\"\necho \"\"\necho \"⚠️ إذا واجهت مشاكل:\"\necho \"   1. جرب: pnpm doctor\"\necho \"   2. ثم: pnpm reset\"\necho \"   3. ثم: pnpm install\"\necho \"\"\n\n# ===================================\n# 11. الخطوات السريعة\n# ===================================\n\necho \"\"\necho \"[⚡] الخطوات السريعة للبدء\"\necho \"---\"\necho \"\"\necho \"1. افتح https://github.com/jo-duchan/tapflow\"\necho \"2. Code → Codespaces → Create codespace on main\"\necho \"3. انتظر انتهاء التثبيت\"\necho \"4. في الطرفية شغّل:\"\necho \"\"\necho \"   pnpm install\"\necho \"   pnpm dev:lean\"\necho \"\"\necho \"5. افتح http://localhost:5173 في المتصفح\"\necho \"6. ابدأ التطوير! 🚀\"\necho \"\"\n\n# ===================================\n# نهاية\n# ===================================\n\necho \"\"\necho \"========================================\"\necho \"لمزيد من المعلومات:\"\necho \"📖 https://www.tapflow.dev\"\necho \"💻 https://github.com/jo-duchan/tapflow\"\necho \"📚 https://github.com/jo-duchan/tapflow/blob/main/CONTRIBUTING.md\"\necho \"========================================\"\n